//! Stress and edge cases from fixtures/stress (generated by
//! scripts/gen_stress.py), run through the real binary and sandbox. Cases
//! that need a sandbox skip when none is available; input errors are checked
//! everywhere.

use std::path::{Path, PathBuf};
use std::process::{Command, Output};

use aco::runner::{select, Limits, SandboxKind};
use serde_json::Value;

const STRESS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/fixtures/stress");

fn aco() -> Command {
    let mut c = Command::new(env!("CARGO_BIN_EXE_aco"));
    // Share one package cache across tests and runs.
    c.env(
        "ACO_CACHE_DIR",
        Path::new(env!("CARGO_TARGET_TMPDIR")).join("aco-cache"),
    );
    c
}

fn fixture(rel: &str) -> PathBuf {
    Path::new(STRESS).join(rel)
}

fn out_dir(name: &str) -> PathBuf {
    let d = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("stress")
        .join(name);
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn stderr(o: &Output) -> String {
    String::from_utf8_lossy(&o.stderr).into_owned()
}

fn sandbox() -> bool {
    match select(SandboxKind::Auto, Limits::default()) {
        Ok(_) => true,
        Err(e) => {
            eprintln!("SKIP sandboxed stress test: {e}");
            false
        }
    }
}

/// Run `aco --plain --json` and return the exit status, stderr and report.
fn run(name: &str, args: &[&str]) -> (Output, Option<Value>) {
    let out = out_dir(name);
    let o = aco()
        .args(["--plain", "--json", "--reps", "3", "-o"])
        .arg(&out)
        .args(args)
        .output()
        .unwrap();
    let report = std::fs::read_dir(&out)
        .unwrap()
        .flatten()
        .find(|e| e.file_name().to_string_lossy().ends_with(".report.json"))
        .map(|e| serde_json::from_str(&std::fs::read_to_string(e.path()).unwrap()).unwrap());
    (o, report)
}

fn confirmed(r: &Value) -> f64 {
    assert_eq!(r["best"]["confirmed"], true, "{:#}", r["best"]);
    r["best"]["speedup"].as_f64().unwrap()
}

// ------------------------------------------------------------ large files

#[test]
fn large_files_find_buried_patterns() {
    if !sandbox() {
        return;
    }
    for n in [300, 1000, 3000] {
        let f = fixture(&format!("large_{n}.py"));
        let (o, r) = run(&format!("large_{n}"), &[f.to_str().unwrap()]);
        assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
        let r = r.unwrap();
        let lines = r["run"]["files"][0]["lines"].as_u64().unwrap();
        assert!(lines as usize >= n, "{lines}");
        // All three rules fire in a large file, and one rewrite does not stop
        // the others: the elite of a later generation carries several.
        let origins: Vec<&str> = r["candidates"]
            .as_array()
            .unwrap()
            .iter()
            .map(|c| c["origin"].as_str().unwrap())
            .collect();
        for rule in ["bubble-sort", "membership", "concat"] {
            assert!(
                origins.iter().any(|o| o.contains(rule)),
                "{rule}: {origins:?}"
            );
        }
        assert!(confirmed(&r) > 5.0);
        let best = &r["best_source"].as_str().unwrap();
        assert!(best.contains("sort(") || best.contains("sorted("));
        assert!(best.contains("known_set") || best.contains("known_set ="));
        let t = &r["timings"];
        assert!(t["parse_ns"].as_u64().unwrap() > 0 && t["search_ns"].as_u64().unwrap() > 0);
    }
}

// ------------------------------------------------------- multi-file project

#[test]
fn project_hot_loop_in_helper_is_reported_then_optimised() {
    if !sandbox() {
        return;
    }
    let main = fixture("project/main.py");
    let (o, r) = run("project", &[main.to_str().unwrap()]);
    assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
    let err = stderr(&o);
    assert!(
        err.contains(
            "the rules find nothing to rewrite in main.py, but they do in shop/inventory.py"
        ),
        "{err}"
    );
    let r = r.unwrap();
    let files: Vec<&str> = r["run"]["files"]
        .as_array()
        .unwrap()
        .iter()
        .map(|f| f["path"].as_str().unwrap())
        .collect();
    assert_eq!(
        files,
        [
            "main.py",
            "helpers.py",
            "shop/__init__.py",
            "shop/inventory.py",
            "shop/pricing.py",
            "shop/util.py"
        ]
    );
    assert_eq!(r["best"]["origin"], "baseline");

    let helper = fixture("project/shop/inventory.py");
    let (o, r) = run(
        "project-mutate",
        &["--mutate", helper.to_str().unwrap(), main.to_str().unwrap()],
    );
    assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
    let r = r.unwrap();
    assert_eq!(r["run"]["mutated"], "shop/inventory.py");
    assert!(confirmed(&r) > 3.0);
    assert!(r["best_source"]
        .as_str()
        .unwrap()
        .contains("discontinued_set"));
    let best = out_dir_path("project-mutate").join("inventory.best.py");
    assert!(best.is_file(), "{best:?}");
}

fn out_dir_path(name: &str) -> PathBuf {
    Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("stress")
        .join(name)
}

fn project(name: &str, files: &[(&str, &str)]) -> PathBuf {
    let root = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join("projects")
        .join(name);
    let _ = std::fs::remove_dir_all(&root);
    for (rel, text) in files {
        let p = root.join(rel);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, text).unwrap();
    }
    root
}

#[test]
fn project_input_errors_name_the_file_and_line() {
    // Policy violations in an imported helper.
    let root = project(
        "policy",
        &[
            ("main.py", "import helper\nprint(helper.f(2))\n"),
            (
                "helper.py",
                "def f(x):\n    y = x + 1\n    return eval('y')\n",
            ),
        ],
    );
    let o = aco().arg(root.join("main.py")).output().unwrap();
    assert_eq!(o.status.code(), Some(2));
    assert!(
        stderr(&o).contains("helper.py:3: uses banned builtin `eval`"),
        "{}",
        stderr(&o)
    );

    // A relative import in the script itself.
    let root = project(
        "relative",
        &[("main.py", "from . import x\nprint(1)\n"), ("x.py", "")],
    );
    let o = aco().arg(root.join("main.py")).output().unwrap();
    assert_eq!(o.status.code(), Some(2));
    assert!(
        stderr(&o).contains("main.py:1: relative import"),
        "{}",
        stderr(&o)
    );

    // A relative import that leaves the package.
    let root = project(
        "relative-up",
        &[
            ("main.py", "import pkg.m\nprint(1)\n"),
            ("pkg/__init__.py", ""),
            ("pkg/m.py", "from ..nowhere import y\n"),
        ],
    );
    let o = aco().arg(root.join("main.py")).output().unwrap();
    assert_eq!(o.status.code(), Some(2));
    assert!(
        stderr(&o)
            .contains("pkg/m.py:1: relative import `..nowhere` goes above the top-level package"),
        "{}",
        stderr(&o)
    );

    // --mutate must name a file the script imports.
    let root = project(
        "mutate-unused",
        &[("main.py", "print(1)\n"), ("other.py", "x = 1\n")],
    );
    let o = aco()
        .arg("--mutate")
        .arg(root.join("other.py"))
        .arg(root.join("main.py"))
        .output()
        .unwrap();
    assert_eq!(o.status.code(), Some(2));
    assert!(
        stderr(&o).contains("is not imported by `main.py`"),
        "{}",
        stderr(&o)
    );

    // A third-party import with no requirements.
    let o = aco().arg(fixture("missing_dep.py")).output().unwrap();
    assert_eq!(o.status.code(), Some(2));
    assert!(
        stderr(&o).contains("missing_dep.py:1: imports `yaml`")
            && stderr(&o).contains("Add `PyYAML`"),
        "{}",
        stderr(&o)
    );

    // The requirements file is validated before anything is installed.
    let o = aco()
        .arg(fixture("bad_requirements/use.py"))
        .output()
        .unwrap();
    assert_eq!(o.status.code(), Some(2));
    assert!(
        stderr(&o).contains("requirements.txt:2")
            && stderr(&o).contains("pip options are not supported"),
        "{}",
        stderr(&o)
    );
}

#[test]
fn optional_imports_and_stdlib_shadowing_are_notes() {
    if !sandbox() {
        return;
    }
    let root = project(
        "optional",
        &[
            (
                "main.py",
                "try:\n    import ujson as json\nexcept ImportError:\n    import json\nimport heapq\nprint(json.dumps([1]))\n",
            ),
            ("heapq.py", "VALUE = 1\n"),
        ],
    );
    let (o, _) = run("optional", &[root.join("main.py").to_str().unwrap()]);
    let err = stderr(&o);
    assert_eq!(o.status.code(), Some(0), "{err}");
    assert!(
        err.contains("`ujson` is imported inside try/except and is not installed"),
        "{err}"
    );
    assert!(
        err.contains("local `heapq.py` shadows the standard library module `heapq`"),
        "{err}"
    );
}

// ------------------------------------------------------------- stdlib code

#[test]
fn stdlib_heavy_code_runs_and_keeps_output() {
    if !sandbox() {
        return;
    }
    let (o, r) = run("stdlib", &[fixture("stdlib_heavy.py").to_str().unwrap()]);
    assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
    let r = r.unwrap();
    assert!(r["run"]["packages"].as_array().unwrap().is_empty());
    assert_eq!(r["run"]["files"].as_array().unwrap().len(), 1);
    // Whatever the verdict, the output check held: the best source is
    // either the original or a confirmed rewrite.
    if r["best"]["confirmed"] == true {
        assert!(r["confirmation"]["oracle_ok"] == true);
    }
}

// ---------------------------------------------------- third-party packages

#[test]
fn numpy_and_a_pure_python_dependency_install_and_run() {
    if !sandbox() {
        return;
    }
    let f = fixture("numpy_project/stats.py");
    let (o, r) = run("numpy", &[f.to_str().unwrap()]);
    let err = stderr(&o);
    assert_eq!(o.status.code(), Some(0), "{err}");
    assert!(
        err.contains("installing numpy==2.3.4, more-itertools==10.5.0"),
        "{err}"
    );
    let r = r.unwrap();
    let pkgs: Vec<String> = r["run"]["packages"]
        .as_array()
        .unwrap()
        .iter()
        .map(|p| {
            format!(
                "{} {}",
                p["name"].as_str().unwrap(),
                p["version"].as_str().unwrap()
            )
        })
        .collect();
    assert_eq!(pkgs, ["more-itertools 10.5.0", "numpy 2.3.4"]);
    assert!(confirmed(&r) > 2.0);
    // The second run is served from the cache.
    let (o, _) = run("numpy-again", &["--gens", "1", f.to_str().unwrap()]);
    assert!(
        stderr(&o).contains("using cached packages"),
        "{}",
        stderr(&o)
    );
}

#[test]
fn a_package_without_wheels_is_refused_by_name() {
    if !sandbox() {
        return;
    }
    let root = project(
        "nowheel",
        &[
            ("requirements.txt", "pycairo==1.20.0\n"),
            ("main.py", "import cairo\nprint(1)\n"),
        ],
    );
    let o = aco()
        .arg("--plain")
        .arg(root.join("main.py"))
        .output()
        .unwrap();
    let err = stderr(&o);
    assert_eq!(o.status.code(), Some(2), "{err}");
    assert!(
        err.contains("`pycairo==1.20.0` has no installable wheel")
            || err.contains("could not reach the package index"),
        "{err}"
    );
}

// ---------------------------------------------------- stdin, argv, exit codes

#[test]
fn stdin_argv_stderr_and_exit_code_are_part_of_the_run() {
    if !sandbox() {
        return;
    }
    let script = fixture("io/count_words.py");
    let input = fixture("io/input.txt");
    let (o, r) = run(
        "io-args",
        &[
            "--stdin",
            input.to_str().unwrap(),
            script.to_str().unwrap(),
            "--",
            "5",
            "fail",
        ],
    );
    assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
    let r = r.unwrap();
    assert_eq!(r["run"]["argv"], serde_json::json!(["5", "fail"]));
    assert_eq!(r["baseline"]["exit_code"], 3);
    assert_eq!(r["baseline"]["stderr"], "processed 5 rounds\n");
    // Without stdin the script sees an empty stream and still runs.
    let (o, r) = run("io-empty", &[script.to_str().unwrap()]);
    assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
    assert!(r.unwrap()["baseline"]["stderr"] == "processed 1 rounds\n");
}

#[test]
fn nondeterministic_output_is_a_clear_error() {
    if !sandbox() {
        return;
    }
    for f in ["io/unseeded_random.py", "io/prints_time.py"] {
        let (o, _) = run("nondet", &[fixture(f).to_str().unwrap()]);
        assert_eq!(o.status.code(), Some(1), "{f}");
        assert!(
            stderr(&o).contains("nondeterministic output") && stderr(&o).contains("seed `random`"),
            "{f}: {}",
            stderr(&o)
        );
    }
    for f in ["io/seeded_random.py", "io/timing_internal.py"] {
        let (o, _) = run("det", &[fixture(f).to_str().unwrap()]);
        assert_eq!(o.status.code(), Some(0), "{f}: {}", stderr(&o));
    }
}

// --------------------------------------------------- encodings and syntax

#[test]
fn crlf_bom_and_tabs_round_trip() {
    if !sandbox() {
        return;
    }
    for (name, check) in [
        (
            "crlf",
            (|b: &[u8]| {
                b.windows(2).any(|w| w == b"\r\n")
                    && !b.windows(2).any(|w| w[1] == b'\n' && w[0] != b'\r')
            }) as fn(&[u8]) -> bool,
        ),
        ("bom", |b: &[u8]| b.starts_with(b"\xEF\xBB\xBF")),
        ("tabs", |b: &[u8]| b.contains(&b'\t')),
    ] {
        let f = fixture(&format!("encoding/{name}.py"));
        let (o, r) = run(name, &[f.to_str().unwrap()]);
        assert_eq!(o.status.code(), Some(0), "{name}: {}", stderr(&o));
        assert!(confirmed(&r.unwrap()) > 2.0, "{name}");
        let best = std::fs::read(out_dir_path(name).join(format!("{name}.best.py"))).unwrap();
        assert!(check(&best), "{name}: {:?}", String::from_utf8_lossy(&best));
    }
}

#[test]
fn unsupported_encodings_and_syntax_are_clear_errors() {
    let cases = [
        (
            "encoding/latin1.py",
            "is not UTF-8 text (byte 0xE9 on line 1)",
        ),
        ("encoding/declared_latin1.py", "declares `coding: latin-1`"),
    ];
    for (f, want) in cases {
        let o = aco().arg(fixture(f)).output().unwrap();
        assert_eq!(o.status.code(), Some(2), "{f}");
        assert!(stderr(&o).contains(want), "{f}: {}", stderr(&o));
    }
    // PEP 701 f-strings: Python 3.12 accepts them, aco's parser does not.
    let host_312 = Command::new("python3")
        .args(["-c", "import sys; sys.exit(sys.version_info < (3, 12))"])
        .status()
        .is_ok_and(|s| s.success());
    let o = aco().arg(fixture("syntax/pep701.py")).output().unwrap();
    assert_eq!(o.status.code(), Some(2));
    let want = if host_312 {
        "uses Python syntax aco cannot parse yet"
    } else {
        "is not valid Python"
    };
    assert!(stderr(&o).contains(want), "{}", stderr(&o));
}

#[test]
fn newer_syntax_that_parses_runs() {
    if !sandbox() {
        return;
    }
    for f in [
        "syntax/pep695.py",
        "syntax/match_stmt.py",
        "encoding/unicode_names.py",
    ] {
        let (o, _) = run("syntax", &[fixture(f).to_str().unwrap()]);
        assert_eq!(o.status.code(), Some(0), "{f}: {}", stderr(&o));
    }
}

#[test]
fn hash_order_dependent_output_can_still_be_optimised() {
    if !sandbox() {
        return;
    }
    // Before per-run hash seeds, every candidate here was rejected as
    // "output differs" because each sandbox hashed strings differently.
    let (o, r) = run(
        "set-output",
        &[fixture("traps/set_output.py").to_str().unwrap()],
    );
    assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
    assert!(confirmed(&r.unwrap()) > 1.2);
}

// ------------------------------------------------------------ too fast

#[test]
fn microsecond_code_is_reported_too_fast_to_measure() {
    if !sandbox() {
        return;
    }
    let (o, r) = run("tiny", &[fixture("tiny.py").to_str().unwrap()]);
    assert_eq!(o.status.code(), Some(0), "{}", stderr(&o));
    let r = r.unwrap();
    assert!(r["stop_reason"]
        .as_str()
        .unwrap()
        .starts_with("too fast to measure"));
    assert_eq!(r["best"]["origin"], "baseline");
    assert!(r["candidates"].as_array().unwrap().is_empty());
    assert!(String::from_utf8_lossy(&o.stdout).contains("too fast to measure reliably"));
}
